import { $gl } from "../../WebGLUtil";
/**
 * @type {number}
 * @private
 */
let $id = 0;
/**
 * @description 新規のテクスチャオブジェクトを作成します。
 *              Create a new texture object.
 *
 * @param  {number} width
 * @param  {number} height
 * @return {ITextureObject}
 * @method
 * @protected
 */
export const execute = (width, height) => {
    return {
        "id": $id++,
        "resource": $gl.createTexture(),
        "width": width,
        "height": height,
        "area": width * height,
        "smooth": false
    };
};
